convert.dart:
class Root {
  final String name;
  final bool ok;
  final dynamic none;
  final dynamic n;
  final dynamic inf;
  final int hex;
  final List<int> list;

  const Root({
    required this.name,
    required this.ok,
    this.none,
    this.n,
    this.inf,
    required this.hex,
    required this.list,
  });

  factory Root.fromJson(Map<String, dynamic> json) => Root(
    name: json['name'] as String,
    ok: json['ok'] as bool,
    none: json['none'],
    n: json['n'],
    inf: json['inf'],
    hex: json['hex'] as int,
    list: (json['list'] as List<dynamic>).map((e) => e as int).toList(),
  );

  Map<String, dynamic> toJson() => {
    'name': name,
    'ok': ok,
    'none': none,
    'n': n,
    'inf': inf,
    'hex': hex,
    'list': list,
  };
}

